<!doctype html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta name="viewport"
    content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0">
  <meta http-equiv="X-UA-Compatible" content="ie=edge">
  <title>Document</title>
</head>

<body>
  <style>
    * {
      margin: 0;
      padding: 0;
    }

    .fields-item {
      margin-bottom: 4px;
    }

    #tag {
      width: 560px;
      height: 320px;
      box-sizing: border-box;
      background-color: #f8f8f8;
      border: 1px solid #e1e1e1;
      border-radius: 10px;
      overflow: hidden;
      display: flex;
      justify-content: center;
      font-size: 20px;
    }
  </style>
  <div id="tag">
    <div style="float: left; width: 300px; padding: 20px 20px; box-sizing: border-box">
      <div id="field1" class="fields-item"></div>
      <div id="field2" class="fields-item"></div>
      <div id="field3" class="fields-item"></div>
      <div id="field4" class="fields-item"></div>
      <div id="field5" class="fields-item"></div>
      <div id="field6" class="fields-item"></div>
      <div id="field7" class="fields-item"></div>
      <div id="field8" class="fields-item"></div>
      <div id="field9" class="fields-item"></div>
    </div>
    <div style="float: right; width: 256px; padding: 50px 20px; box-sizing: border-box">
      <img id="qrCode" width="200" height="200" src="" />
    </div>
  </div>
</body>

</html>' WHERE id = 1;

